  await page.route('**/api/upsell/discover-location', (route) =>
    route.fulfill(json({ candidates: BENTO_FIX.candidates, suppressed: [] })),
  );
  // Demand + attribution + media ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â inert 200s so nothing hangs or errors.
